import sys

try:
    from openpyxl import load_workbook
except ImportError:
    print("ERROR: openpyxl not available")
    sys.exit(1)

try:
    wb = load_workbook('budget.xlsx', data_only=False)
except FileNotFoundError:
    print("ERROR: budget.xlsx not found")
    sys.exit(1)

print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} (dims {ws.dimensions}, max_row {ws.max_row}, max_col {ws.max_column}) ===")
    for row in ws.iter_rows():
        vals = []
        for c in row:
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))

import zipfile
import re
import sys
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'rel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

try:
    z = zipfile.ZipFile('budget.xlsx')
except FileNotFoundError:
    print("ERROR: budget.xlsx not found")
    sys.exit(1)

print("Archive entries:")
for n in z.namelist():
    print("  ", n)

# Shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared.append(text)

# Workbook sheets
wbroot = ET.fromstring(z.read('xl/workbook.xml'))
relsroot = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {}
for rel in relsroot.findall('rel:Relationship', NS):
    relmap[rel.get('Id')] = rel.get('Target')

sheet_files = []
for sh in wbroot.find('m:sheets', NS):
    rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    name = sh.get('name')
    target = relmap.get(rid, '')
    sheet_files.append((name, target))

print("\nSheets:", [(n, t) for n, t in sheet_files])

def col_letter_to_idx(col):
    idx = 0
    for ch in col:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx

def cell_ref(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    return col_letter_to_idx(m.group(1)), int(m.group(2))

for name, target in sheet_files:
    path = 'xl/' + target.lstrip('/')
    if not path.endswith('.xml'):
        path = path + '.xml'
    print(f"\n=== Sheet: {name} ===")
    root = ET.fromstring(z.read(path))
    sd = root.find('m:sheetData', NS)
    for row in sd.findall('m:row', NS):
        out = []
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            isv = c.find('m:is', NS)
            val = None
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr' and isv is not None:
                val = ''.join(x.text or '' for x in isv.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            elif v is not None:
                val = v.text
            if val is not None:
                out.append(f"{ref}={val!r}")
        if out:
            print(" | ".join(out))

